import {materials,services,statusLabels,money,balance,total,selectedQuote,directorQuote,normalizeText,filterRequests,deliveryRows,csvContent} from './domain.mjs';
let state={requests:[],orders:[],contracts:[],movements:[],catalog:[],suppliers:[],works:[],revision:0};
let session=null,busy=false,ready=false;const pendingKeys=new Map();
materials.splice(0);services.splice(0);
async function api(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options});if(!r.ok){let message;try{message=(await r.json()).error;}catch{}throw Error(message||'Não foi possível acessar o servidor.');}return r.json();}
async function refresh(){const next=await api('/api/state');state=next;materials.splice(0,materials.length,...state.catalog);setServices();document.querySelector('#work').innerHTML='<option value="all">Todas as obras autorizadas</option>'+state.works.map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('');if(work!=='all'&&!state.works.some(w=>w.id===work))work='all';document.querySelector('#work').value=work;render();}
function setServices(selectedWork){const id=selectedWork||work;const rows=id==='all'?Object.values(state.budgetServices||{}).flat():state.budgetServices?.[id]||[];services.splice(0,services.length,...new Map(rows.map(s=>[s.id,s])).values());}
async function execute(action,payload={},message){if(!ready)throw Error('Aguarde a conexão com o ERP.');const record=state.requests.find(r=>r.id===payload.id)||state.orders.find(r=>r.id===payload.id)||state.contracts.find(r=>r.id===payload.id);const body={action,...payload,...(record?{expectedRevision:record.revision||0}:{})};const signature=JSON.stringify(body),key=pendingKeys.get(signature)||crypto.randomUUID();pendingKeys.set(signature,key);const result=await api('/api/commands',{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key},body:signature});pendingKeys.delete(signature);await refresh();if(message)toast(message);return result;}
async function connect(){try{session=await api('/api/session');document.querySelector('#identity').textContent=session.name;document.querySelector('.demo').textContent='Dados compartilhados · '+session.name;ready=true;await refresh();}catch(e){ready=false;content.innerHTML=heading('ACESSO AO ERP','Conexão necessária',esc(e.message),'<button data-action="reconnect">Tentar novamente</button>');}}
const workOptions=selected=>state.works.map(w=>`<option value="${esc(w.id)}" ${w.id===selected?'selected':''}>${esc(w.name)}</option>`).join('');
function catalogWork(){return work==='all'?state.works[0]?.id:work;}
function permitted(role,w){return session?.access.some(a=>(!w||a.work_id===w)&&a.role===role);}
const viewFilters={},openGroups=new Set(['Compras']);
let work='all';const content=document.querySelector('#content'),dialog=document.querySelector('#dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v?new Date(v.length===10?v+'T12:00:00':v).toLocaleDateString('pt-BR'):'—';
const nav=[['inicio','◈','Painel de suprimentos',''],['solicitacoes','▤','Solicitações','Compras'],['cotacoes','⇄','Cotações','Compras'],['aprovacoes','✓','Aprovações','Compras'],['pedidos','▧','Pedidos','Compras'],['recebimentos','↓','Recebimentos','Compras'],['contratos','▥','Contratos','Contratos e Medições'],['medicoes','✓','Medições','Contratos e Medições'],['estoque','▦','Consulta de estoque','Estoque'],['movimentos','⇅','Movimentações','Estoque'],['cadastros','⊞','Materiais','Cadastros'],['fornecedores','◉','Fornecedores','Cadastros'],['relatorios','▤','Acompanhamento','Relatórios'],['orcamento','◷','Orçamento por serviço','Relatórios']];
const filtered=arr=>arr.filter(x=>work==='all'||x.work===work);
const badge=r=>`<span class="badge ${esc(r.status)}">${statusLabels[r.status]}</span>`;
const empty=(title,desc)=>`<div class="empty"><strong>${title}</strong>${desc}</div>`;
const heading=(eyebrow,title,subtitle,action='')=>`<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;
const panel=(title,body,detail='')=>`<div class="panel"><div class="panel-head"><h2>${title}</h2><small>${detail}</small></div>${body}</div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;
const reqRows=arr=>arr.map(r=>`<tr><td><strong>${r.id}</strong><small>${esc(r.work)}</small></td><td><strong>${esc(r.purpose)}</strong><small>${r.items.length} item(ns) · ${esc(r.requester)}</small></td><td>${date(r.items.map(i=>i.neededDate).filter(Boolean).sort()[0])}<small>Primeira necessidade</small></td><td>${badge(r)}</td><td><button data-action="request" data-id="${r.id}">Abrir →</button></td></tr>`).join('');
const reqTable=arr=>arr.length?table(['Solicitação','Finalidade','Necessário em','Etapa',''],reqRows(arr)):empty('Nenhuma solicitação nesta etapa','As solicitações aparecerão aqui conforme avançarem no processo.');
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4000);}
function modal(title,body){document.querySelector('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close" aria-label="Fechar">×</button></div><div class="dialog-body">${body}<div class="error" id="error" role="alert"></div></div>`;if(!dialog.open)dialog.showModal();restrictControls();}
function showError(e){document.querySelector('#error')?.replaceChildren(document.createTextNode(e.message));}
async function attempt(fn){if(busy)return;busy=true;document.body.setAttribute('aria-busy','true');const buttons=[...document.querySelectorAll('button')].filter(b=>!b.disabled);buttons.forEach(b=>b.disabled=true);try{await fn();}catch(e){showError(e);toast(e.message);}finally{busy=false;document.body.removeAttribute('aria-busy');buttons.forEach(b=>b.disabled=false);}}
function render(){const page=currentPage();renderNav(page);document.querySelector('#crumb').textContent='Suprimentos / '+(nav.find(n=>n[0]===page)?.[2]||'Painel');const f=filtersFor(page);const rs=filterRequests(filtered(state.requests),['solicitacoes','cotacoes','aprovacoes'].includes(page)?f:{}),os=filtered(state.orders).filter(o=>page!=='pedidos'||documentMatches(o,f)),cs=filtered(state.contracts).filter(c=>!['contratos','medicoes'].includes(page)||documentMatches(c,f));switch(page){
case 'inicio':{const pending=rs.filter(r=>['engineering','director','returned'].includes(r.status));const committed=os.reduce((s,o)=>s+o.items.reduce((v,i)=>v+i.qty*i.price,0)+o.freight,0)+cs.reduce((s,c)=>s+c.items.reduce((v,i)=>v+i.qty*i.price,0)+(c.freight||0),0);content.innerHTML=heading('OPERAÇÃO EM PERSPECTIVA','Painel de suprimentos','Solicitações, decisões e entregas em uma visão compartilhada.','<button class="primary" data-action="new">＋ Nova solicitação</button>')+`<div class="cards"><div class="card"><div class="card-label">Solicitações abertas <span>↗</span></div><div class="metric">${rs.filter(r=>!['received','contracted'].includes(r.status)).length}</div><small>Necessidades em acompanhamento</small></div><div class="card"><div class="card-label">Aguardando aprovação <span>✓</span></div><div class="metric">${pending.length}</div><small>Engenharia e diretoria</small></div><div class="card"><div class="card-label">Cotações em andamento <span>⇄</span></div><div class="metric">${rs.filter(r=>r.status==='quoting').length}</div><small>Comparação e negociação</small></div><div class="card accent"><div class="card-label">Valor contratado <span>◷</span></div><div class="metric money">${money(committed)}</div><small>Pedidos e serviços · compromissos</small></div></div><div class="grid"><div>${panel('O que precisa de atenção',reqTable(pending),'APROVAÇÕES')}${panel('Obras no ambiente',`<div class="panel-body">${state.works.map(w=>w.id).filter(w=>work==='all'||work===w).map(w=>{const count=state.requests.filter(r=>r.work===w).length;return `<div class="work-card"><div class="work-title"><strong>${w}</strong><span>${count} solicitações</span></div><div class="bar"><i style="width:${count*20}%"></i></div></div>`;}).join('')}</div>`,'OBRAS AUTORIZADAS')}</div><div>${panel('Um fluxo, quatro equipes',`<div class="panel-body flow">${[['Almoxarifado','Identifica a necessidade e consulta o estoque.'],['Engenharia','Valida especificações e orçamento.'],['Suprimentos','Compara propostas e condições.'],['Diretor de engenharia','Aprova a contratação.']].map(([t,d],i)=>`<div class="flow-row"><span class="number">0${i+1}</span><div>${t}<small>${d}</small></div></div>`).join('')}<div class="note" style="margin-top:10px">Cada etapa exige a função responsável e acesso à obra.</div></div>`)}${panel('Decisões rastreáveis','<div class="panel-body"><p class="subtitle">Aprovações e devoluções guardam o motivo e a etapa. Recebimentos atualizam o estoque, sem representar pagamento.</p></div>')}</div></div>`;break;}
case 'solicitacoes':content.innerHTML=heading('NECESSIDADES DA OBRA','Solicitações','Materiais e serviços com destino, prazo e vínculo ao orçamento.','<button class="primary" data-action="new">＋ Nova solicitação</button>')+panel('Todas as solicitações',reqTable(rs),`${rs.length} REGISTROS`);break;
case 'cotacoes':content.innerHTML=heading('SUPRIMENTOS','Cotações','Compare escopo e condições antes de propor uma contratação.')+panel('Em negociação',reqTable(rs.filter(r=>r.status==='quoting')));break;
case 'aprovacoes':content.innerHTML=heading('DECISÕES','Aprovações','Duas conferências: necessidade técnica e contratação comercial.')+panel('Engenharia',reqTable(rs.filter(r=>['engineering','returned'].includes(r.status))))+panel('Diretor de engenharia',reqTable(rs.filter(r=>r.status==='director')));break;
case 'pedidos':content.innerHTML=heading('COMPRAS','Pedidos de compra','Acompanhe o recebimento por item e o saldo de cada entrega.')+panel('Pedidos emitidos',os.length?table(['Pedido','Fornecedor','Valor dos materiais','Próxima chegada','Recebimento',''],os.map(o=>`<tr><td><strong>${o.id}</strong><small>${o.work} · ${o.requestId}</small></td><td>${esc(o.supplier)}</td><td>${money(o.items.reduce((s,i)=>s+i.qty*i.price,0))}</td><td>${date(o.items.filter(i=>i.received<i.qty).map(i=>i.estimatedArrival).filter(Boolean).sort()[0])}</td><td>${o.items.every(i=>i.received===i.qty)?'<span class="badge received">Completo</span>':o.items.some(i=>i.received)?'<span class="badge director">Parcial</span>':'<span class="badge">Pendente</span>'}</td><td><button data-action="order" data-id="${o.id}">Conferir entrega →</button></td></tr>`).join('')):empty('Nenhum pedido emitido','Aprove uma contratação de materiais na tela de Aprovações.'));break;
case 'contratos':content.innerHTML=heading('EXECUÇÃO CONTRATADA','Contratos e medições','Registre o executado e acompanhe o saldo de serviços contratados.')+panel('Contratos emitidos',cs.length?table(['Contrato','Fornecedor','Valor dos serviços','Medido acumulado',''],cs.map(c=>`<tr><td><strong>${c.id}</strong><small>${c.work} · ${c.requestId}</small></td><td>${esc(c.supplier)}</td><td>${money(c.items.reduce((s,i)=>s+i.qty*i.price,0))}</td><td>${money(c.measurements.reduce((s,m)=>s+m.value,0))}</td><td><button data-action="contract" data-id="${c.id}">Abrir medição →</button></td></tr>`).join('')):empty('Nenhum contrato emitido','Os contratos aparecem após a contratação de serviços.'));break;
case 'estoque':{const works=work==='all'?state.works.map(w=>w.id):[work];content.innerHTML=heading('ALMOXARIFADO','Estoque por obra','Entradas e saídas registradas. Saldo físico registrado, sem reservas.','<button class="primary" data-action="withdraw">Registrar saída</button>')+panel('Disponibilidade',table(['Material','Obra','Unidade','Saldo físico'],works.flatMap(w=>materials.map(m=>`<tr><td><strong>${esc(m.name)}</strong></td><td>${w}</td><td>${m.unit}</td><td><strong>${balance(state,w,m.id)}</strong></td></tr>`)).join('')))+panel('Movimentações recentes',table(['Data','Material','Obra','Tipo','Quantidade','Responsável / documento'],filtered(state.movements).slice().reverse().map(m=>`<tr><td>${date(m.at)}</td><td>${esc(materials.find(a=>a.id===m.material)?.name)}</td><td>${m.work}</td><td><span class="badge ${m.kind==='in'?'received':'quoting'}">${m.kind==='in'?'Entrada':'Saída'}</span></td><td>${m.qty}</td><td>${esc(m.who)}<small>${esc(m.nf||m.floor||'')}</small></td></tr>`).join('')));break;}
case 'orcamento':{const ws=work==='all'?state.works.map(w=>w.id):[work];content.innerHTML=heading('CONTROLE POR SERVIÇO','Orçamento','Valores configurados por obra para acompanhar os vínculos das contratações.')+'<div class="note">O comprometido soma itens de pedidos e contratos aprovados, sem frete. Recebimentos e saídas não são somados novamente. Critérios financeiros oficiais serão definidos em outra etapa.</div>'+panel('Serviços por obra',table(['Obra / serviço','Referência configurada','Comprometido (itens)','Saldo da referência'],ws.flatMap(w=>(state.budgetServices?.[w]||[]).map(s=>{const used=[...state.orders,...state.contracts].filter(o=>o.work===w).flatMap(o=>o.items).filter(i=>i.service===s.id).reduce((v,i)=>v+i.qty*i.price,0);return `<tr><td><strong>${esc(s.name)}</strong><small>${w}</small></td><td>${s.budget===null?'Não definido':money(s.budget)}</td><td>${money(used)}</td><td>${s.budget===null?'—':money(s.budget-used)}</td></tr>`;})).join('')));break;}
case 'cadastros':content.innerHTML=materialPage();break;
case 'recebimentos':content.innerHTML=receivingPage();break;
case 'movimentos':content.innerHTML=movementsPage();break;
case 'medicoes':content.innerHTML=measurementsPage(cs);break;
case 'fornecedores':content.innerHTML=supplierPage();break;
case 'relatorios':content.innerHTML=reportsPage();break;
default:location.hash='inicio';}decoratePage(page);restrictControls();}
function serviceOptions(selected){return '<option value="">Selecione o serviço</option>'+services.map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${esc(s.name)}</option>`).join('');}
function itemsTable(r){return table(['Item','Quantidade','Data necessária / local','Serviço do orçamento'],r.items.map(i=>`<tr><td><strong>${esc(i.name)}</strong><small>${i.kind==='service'?'Serviço':'Material'}${i.material?` · estoque: ${balance(state,r.work,i.material)} ${i.unit}`:''}</small></td><td>${i.qty} ${esc(i.unit)}</td><td>${date(i.neededDate)}<small>${esc(i.location||'Local não informado')}</small></td><td>${esc(services.find(s=>s.id===i.service)?.name||'Pendente')}</td></tr>`).join(''));}
function history(r){return `<div class="history">${r.history.length?r.history.slice().reverse().map(h=>`<p>${esc(h.text)}<small>${esc(h.who)} · ${esc(new Date(h.at).toLocaleString('pt-BR'))}</small></p>`).join(''):'<p>Nenhuma ação registrada.</p>'}</div>`;}
function openRequest(id){const r=state.requests.find(r=>r.id===id);setServices(r.work);let controls='';if(['engineering','returned'].includes(r.status)){controls=`<h3 style="margin-top:20px">Conferência da engenharia</h3>${r.items.map((i,index)=>`<label>${esc(i.name)}<select id="service-${index}">${serviceOptions(i.service)}</select></label>`).join('')}<label>Justificativa de despesa não prevista<textarea id="justification">${esc(r.justification||'')}</textarea></label><div class="actions"><button data-action="edit" data-id="${r.id}">Editar solicitação</button><button class="danger" data-action="reject" data-id="${r.id}">Devolver</button><button class="primary" data-action="approve-engineering" data-id="${r.id}">Aprovar necessidade</button></div>`;}else if(r.status==='quoting'){controls=`<div class="actions"><button data-action="edit" data-id="${r.id}">Revisar solicitação</button><button class="primary" data-action="quotes" data-id="${r.id}">Abrir comparativo →</button></div>`;}else if(r.status==='director'){controls=`<h3 style="margin-top:20px">Contratação proposta</h3>${quotesView(r,false)}${allocationView(r,'director')}${r.exception?`<div class="note">Exceção às três propostas: ${esc(r.exception)}</div>`:''}<div class="actions"><button class="danger" data-action="reject" data-id="${r.id}">Devolver a suprimentos</button><button class="primary" data-action="approve-director" data-id="${r.id}">Aprovar e emitir</button></div>`;}modal(`${r.id} · ${r.work}`,`<div class="split"><div><p class="kicker">Finalidade</p><h3>${esc(r.purpose)}</h3><p class="subtitle">${esc(r.requester)} · Datas e locais definidos por item</p></div>${badge(r)}</div><div class="steps"><span class="step ${['engineering','returned'].includes(r.status)?'current':''}">01 Necessidade</span><span class="step ${r.status==='quoting'?'current':''}">02 Cotação</span><span class="step ${r.status==='director'?'current':''}">03 Aprovação</span><span class="step ${['ordered','contracted','received'].includes(r.status)?'current':''}">04 Formalização</span></div>${itemsTable(r)}${controls}<h3 style="margin-top:25px">Histórico</h3>${history(r)}`);}
function quotesView(r,interactive){return r.quotes.length?`<div class="quote-grid">${r.quotes.map(q=>`<div class="quote-card ${q.selected?'selected':''}"><strong>${esc(q.supplier)}</strong><div class="price">${money(total(r,q))}</div><p>Frete: ${money(q.freight)}</p><p>Prazo: ${q.days} dias · ${esc(q.payment)}</p><p>${esc(q.scope)}</p>${attachmentsView(q.attachments)}${q.prices.map((p,i)=>`<p>${esc(r.items[i].name)}: ${money(p)}/${esc(r.items[i].unit)}</p>`).join('')}${interactive?`<button class="small-button ${q.selected?'primary':''}" data-action="select-quote" data-id="${r.id}" data-q="${q.id}">${r.items.every((_,i)=>selectedQuote(r,i)?.id===q.id)?'✓ Sugerido para todos os itens':'Sugerir para todos os itens'}</button><button class="small-button" data-action="quote-files" data-id="${r.id}" data-q="${q.id}">Adicionar anexo</button>`:q.selected?'<span class="badge received">Sugestão de suprimentos</span>':''}</div>`).join('')}</div>`:empty('Nenhuma proposta cadastrada','Adicione as condições dos fornecedores para comparar.');}
function allocationView(r,mode){if(!r.quotes.length)return '';const director=mode==='director';return `<h3 style="margin-top:20px">${director?'Decisão do diretor por item':'Sugestão de suprimentos por item'}</h3>${director?'<div class="note">Confira a sugestão de suprimentos e escolha o fornecedor. Sua decisão define o pedido. A previsão inicial usa o prazo da proposta a partir de hoje; confirme ou ajuste por item.</div>':''}${table(director?['Item / necessidade','Sugestão de suprimentos','Decisão do diretor / chegada estimada']:['Item','Fornecedor sugerido'],r.items.map((item,index)=>`<tr><td>${esc(item.name)}<small>${item.qty} ${esc(item.unit)} · ${date(item.neededDate)} · ${esc(item.location)}</small></td>${director?`<td>${esc(selectedQuote(r,index)?.supplier||'Sem sugestão')}</td>`:''}<td><select aria-label="${director?'Decisão do diretor':'Sugestão de fornecedor'} para ${esc(item.name)}" ${director?`data-decision="${index}"`:`data-allocation="${index}"`}><option value="">${director?'Diretor: escolha o fornecedor':'Selecione a sugestão'}</option>${r.quotes.map(q=>`<option value="${q.id}" ${(director?directorQuote(r,index):selectedQuote(r,index))?.id===q.id?'selected':''}>${esc(q.supplier)} · ${money(q.prices[index])}/${esc(item.unit)}</option>`).join('')}</select>${director?`<label>Chegada estimada<input type="date" data-arrival="${index}" value="${esc(item.estimatedArrival||'')}" required></label>`:''}</td></tr>`).join(''))}`;}
function openQuotes(id){const r=state.requests.find(r=>r.id===id);setServices(r.work);modal(`Comparativo · ${r.id}`,`<p class="subtitle" style="margin-bottom:20px">${esc(r.purpose)} · ${r.work} · ${r.quotes.length}/3 propostas</p>${quotesView(r,true)}${allocationView(r,true)}<div class="actions"><button data-action="add-quote" data-id="${id}">＋ Adicionar proposta</button></div><label style="margin-top:20px">Justificativa de exceção (se houver menos de três fornecedores)<textarea id="exception">${esc(r.exception||'')}</textarea></label><div class="note">Suprimentos sugere fornecedores por item; o diretor toma a decisão final. O frete informado será aplicado uma vez para cada fornecedor contratado; valores podem precisar de nova negociação após a divisão.</div><div class="actions"><button data-action="request" data-id="${id}">Voltar</button><button class="primary" data-action="send-director" data-id="${id}">Enviar ao diretor →</button></div>`);document.querySelectorAll('[data-allocation]').forEach(el=>el.onchange=()=>attempt(async()=>{const allocations=r.items.map((_,index)=>selectedQuote(r,index)?.id||'');allocations[Number(el.dataset.allocation)]=el.value;await execute('suggest',{id,allocations});openQuotes(id);}));}

function addQuote(id){const r=state.requests.find(r=>r.id===id);modal('Adicionar proposta',`<form id="quote-form"><div class="fields"><label class="wide">Fornecedor<input name="supplier" list="supplier-options" required placeholder="Selecione ou informe o fornecedor"></label><datalist id="supplier-options">${state.suppliers.map(s=>`<option value="${esc(s.name)}"></option>`).join('')}</datalist><label>Frete (R$)<input name="freight" type="number" min="0" step="0.01" value="0" required></label><label>Prazo de entrega (dias)<input name="days" type="number" min="1" value="7" required></label><label>Condições de pagamento<input name="payment" required value="28 dias"></label><label>Escopo e ressalvas<input name="scope" required value="Escopo integral"></label></div><h3>Preço unitário por item</h3>${r.items.map((i,index)=>`<label>${esc(i.name)} · ${i.qty} ${esc(i.unit)}<input name="price-${index}" type="number" min="0.01" step="0.01" required placeholder="Preço por ${esc(i.unit)}"></label>`).join('')}${uploadField("quote-files","Anexos da proposta")}<div class="actions"><button type="button" data-action="quotes" data-id="${id}">Cancelar</button><button class="primary">Salvar proposta</button></div></form>`);document.querySelector('#quote-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=new FormData(e.target);const supplier=f.get('supplier').trim();if(r.quotes.some(q=>q.supplier.toLowerCase()===supplier.toLowerCase()))throw Error('Este fornecedor já possui uma proposta neste comparativo.');const attachments=await storeAttachments(document.querySelector('#quote-files').files,'request',id,'quote');await execute('quote',{id,supplier,freight:Number(f.get('freight')),days:Number(f.get('days')),payment:f.get('payment'),scope:f.get('scope'),prices:r.items.map((_,i)=>Number(f.get('price-'+i))),files:attachments.map(a=>a.id)},'Proposta cadastrada.');openQuotes(id);});};}
function requestForm(existing){if(existing&&!['engineering','returned','quoting','director'].includes(existing.status)){toast('Pedido ou contrato já emitido: revisão contratual ainda não disponível.');return;}const rows=existing?structuredClone(existing.items):[{kind:materials.length?'material':'service',material:materials[0]?.id,name:materials[0]?.name||'',unit:materials[0]?.unit||'vb',qty:1,service:''}];modal(existing?'Revisar solicitação':'Nova solicitação',`<form id="request-form"><div class="fields"><label>Obra<select name="work" id="form-work">${workOptions(existing?.work||catalogWork())}</select></label><label>Solicitante<input name="requester" readonly value="${esc(existing?.requester||session?.name)}"></label><label class="wide">Finalidade<input name="purpose" required placeholder="Para que os itens serão utilizados?" value="${esc(existing?.purpose||'')}"></label></div><h3>Itens da solicitação</h3><div id="form-items"></div><button type="button" id="add-item" class="small-button">＋ Adicionar item</button><p class="subtitle" style="margin-top:15px">Anexos disponíveis nas cotações, pedidos e recebimentos.</p>${existing?'<div class="note" style="margin-top:15px">Salvar uma revisão reinicia a aprovação técnica e arquiva as cotações anteriores no histórico.</div>':''}<div class="actions"><button type="button" data-action="close">Cancelar</button><button class="primary">${existing?'Salvar revisão':'Enviar à engenharia'}</button></div></form>`);
const renderItems=()=>{setServices(document.querySelector('#form-work').value);document.querySelector('#form-items').innerHTML=rows.map((i,index)=>`<div class="line-item"><div class="split"><strong>Item ${index+1}</strong>${rows.length>1?`<button type="button" class="small-button" data-remove="${index}">Remover</button>`:''}</div><div class="fields"><label>Tipo<select data-row="${index}" data-field="kind"><option value="material" ${i.kind==='material'?'selected':''}>Material</option><option value="service" ${i.kind==='service'?'selected':''}>Serviço</option></select></label>${i.kind==='material'?`<label>Material<select data-row="${index}" data-field="material">${materials.map(m=>`<option value="${m.id}" ${i.material===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label>`:`<label>Descrição do serviço<input data-row="${index}" data-field="name" required value="${esc(i.name)}"></label>`}<label>Quantidade<input type="number" data-row="${index}" data-field="qty" min="0.01" step="0.01" required value="${i.qty}"></label><label>Unidade<input data-row="${index}" data-field="unit" ${i.kind==='material'?'readonly':''} required value="${esc(i.unit)}"></label><label style="grid-column:span 2">Serviço do orçamento (engenharia pode completar)<select data-row="${index}" data-field="service">${serviceOptions(i.service)}</select></label><label>Data necessária do item<input type="date" data-row="${index}" data-field="neededDate" required value="${esc(i.neededDate||'')}"></label><label>Local do item<input data-row="${index}" data-field="location" required placeholder="Ex.: 10º pavimento, torre A" value="${esc(i.location||'')}"></label></div>${i.kind==='material'?`<div class="stock-hint">Estoque na obra: ${balance(state,document.querySelector('#form-work').value,i.material)} ${esc(i.unit)}</div>`:''}</div>`).join('');document.querySelectorAll('[data-row]').forEach(el=>el.onchange=()=>{const i=rows[Number(el.dataset.row)],field=el.dataset.field;i[field]=field==='qty'?Number(el.value):el.value;if(field==='kind'){if(i.kind==='service'){delete i.material;i.name='';i.unit='vb';}else{Object.assign(i,{material:materials[0]?.id,name:materials[0]?.name||'',unit:materials[0]?.unit||''});}renderItems();}if(field==='material'){const m=materials.find(m=>m.id===el.value);i.name=m.name;i.unit=m.unit;renderItems();}});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{rows.splice(Number(b.dataset.remove),1);renderItems();});};renderItems();document.querySelector('#form-work').onchange=renderItems;document.querySelector('#add-item').onclick=()=>{rows.push({kind:materials.length?'material':'service',material:materials[0]?.id,name:materials[0]?.name||'',unit:materials[0]?.unit||'vb',qty:1,service:''});renderItems();};document.querySelector('#request-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=new FormData(e.target);if(rows.some(i=>!i.name.trim()||!i.unit.trim()||!Number.isFinite(i.qty)||i.qty<=0||!i.neededDate||!i.location?.trim()))throw Error('Confira descrição, quantidade, data necessária e local de todos os itens.');const result=await execute(existing?'edit':'create',{...(existing?{id:existing.id}:{}),work:f.get('work'),purpose:f.get('purpose'),items:rows},'Solicitação enviada à engenharia.');openRequest(existing?.id||result.id);});};}
function openOrder(id){const o=state.orders.find(o=>o.id===id);const complete=o.items.every(i=>i.received===i.qty);modal(`${o.id} · Recebimento`, `<p class="subtitle">${o.work} · ${esc(o.supplier)} · ${o.requestId}</p><h3 style="margin-top:20px">Programação por item</h3><form id="arrival-form">${table(['Item / local','Data necessária','Chegada estimada'],o.items.map((i,index)=>`<tr><td>${esc(i.name)}<small>${esc(i.location||'Local não informado')}</small></td><td>${date(i.neededDate)}</td><td><input type="date" name="arrival-${index}" aria-label="Chegada estimada ${esc(i.name)}" value="${esc(i.estimatedArrival||'')}" required></td></tr>`).join(''))}<div class="actions"><button>Salvar previsões de chegada</button></div></form><h3 style="margin-top:20px">Anexos do pedido</h3>${attachmentsView(o.attachments)}<form id="order-files-form">${uploadField('order-files','Adicionar anexos ao pedido')}<div class="actions"><button>Salvar anexos do pedido</button></div></form><h3 style="margin-top:20px">Conferência da entrega</h3><form id="receive-form">${table(['Material','Pedido','Recebido','Pendente','Receber agora'],o.items.map((i,index)=>`<tr><td>${esc(i.name)}<small>Chegada estimada: ${date(i.estimatedArrival)}</small></td><td>${i.qty}</td><td>${i.received}</td><td>${i.qty-i.received}</td><td><input aria-label="Quantidade recebida ${esc(i.name)}" name="qty-${index}" type="number" step="0.01" min="0" max="${i.qty-i.received}" value="0" ${complete?'disabled':''}></td></tr>`).join(''))}<div class="fields" style="margin-top:20px"><label>Nota fiscal<input name="nf" required placeholder="Número da nota fiscal" ${complete?'disabled':''}></label><label>Divergências / observações<input name="note" placeholder="Opcional" ${complete?'disabled':''}></label></div>${complete?'':uploadField('receipt-files','Anexos deste recebimento')}<div class="note">As quantidades recebidas geram entrada no estoque da obra. Esta ação não registra pagamento.</div><div class="actions"><button type="button" data-action="close">Fechar</button>${complete?'<span class="badge received">Entrega completa</span>':'<button class="primary">Registrar recebimento</button>'}</div></form><h3 style="margin-top:20px">Entregas registradas</h3>${o.receipts.length?o.receipts.map(r=>`<p class="subtitle">${date(r.at)} · NF ${esc(r.nf)} · ${esc(r.note||'Sem divergências informadas')}</p>${attachmentsView(r.attachments)}`).join(''):'<p class="subtitle">Nenhuma entrega registrada.</p>'}`);
 document.querySelector('#arrival-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=new FormData(e.target);await execute('arrival',{id,arrivals:o.items.map((_,index)=>f.get('arrival-'+index))},'Previsões atualizadas por item.');openOrder(id);});};
 document.querySelector('#order-files-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const files=document.querySelector('#order-files').files;if(!files.length)throw Error('Selecione um anexo.');const attachments=await storeAttachments(files,'order',id,'order');await execute('orderFiles',{id,files:attachments.map(a=>a.id)},'Anexos registrados.');openOrder(id);});};
 document.querySelector('#receive-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=new FormData(e.target),quantities=o.items.map((_,i)=>Number(f.get('qty-'+i)));const attachments=await storeAttachments(document.querySelector('#receipt-files').files,'order',id,'receipt');await execute('receive',{id,quantities,nf:f.get('nf'),note:f.get('note'),files:attachments.map(a=>a.id)},'Recebimento registrado e estoque atualizado.');openOrder(id);});};}

function stockOut(){modal('Registrar saída de material',`<form id="out-form"><div class="fields"><label>Obra<select name="work">${workOptions(catalogWork())}</select></label><label>Material<select name="material">${materials.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>Quantidade<input name="qty" type="number" min="0.01" step="0.01" required></label><label>Quem retirou<input name="who" required></label><label>Serviço de destino<select name="service" required>${serviceOptions('')}</select></label><label>Pavimento (opcional)<input name="floor"></label></div><div class="stock-hint" id="out-balance"></div><div class="actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Registrar saída</button></div></form>`);const form=document.querySelector('#out-form');const hint=()=>{const f=new FormData(form),m=materials.find(m=>m.id===f.get('material'));setServices(f.get('work'));const serviceSelect=form.querySelector('[name=service]');serviceSelect.innerHTML=serviceOptions(serviceSelect.value);document.querySelector('#out-balance').textContent=`Saldo físico: ${balance(state,f.get('work'),m.id)} ${m.unit}`;};form.onchange=hint;hint();form.onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=new FormData(form);await execute('withdraw',{...Object.fromEntries(f),recipient:f.get('who'),qty:Number(f.get('qty')),expectedStateRevision:state.revision},'Saída registrada.');dialog.close();});};}
function openContract(id){const c=state.contracts.find(c=>c.id===id);modal(`${c.id} · Medição`, `<p class="subtitle">${c.work} · ${esc(c.supplier)} · ${c.requestId}</p><form id="measure-form">${table(['Serviço','Contratado','Medido','Saldo','Medir agora'],c.items.map((i,index)=>`<tr><td>${esc(i.name)}</td><td>${i.qty} ${esc(i.unit)}</td><td>${i.measured}</td><td>${i.qty-i.measured}</td><td><input aria-label="Quantidade medida ${esc(i.name)}" name="qty-${index}" type="number" step="0.01" min="0" max="${i.qty-i.measured}" value="0"></td></tr>`).join(''))}<label style="margin-top:20px">Período da medição<input name="period" required placeholder="Ex.: 01 a 15/10/2026"></label><div class="note">Registro do executado. Retenções, emissão de boletins e aprovação de medições serão detalhadas na próxima etapa. Não representa pagamento.</div><div class="actions"><button type="button" data-action="close">Fechar</button><button class="primary">Registrar medição</button></div></form><h3 style="margin-top:20px">Medições registradas</h3>${c.measurements.map(m=>`<p class="subtitle">${esc(m.period)} · ${money(m.value)}</p>`).join('')||'<p class="subtitle">Nenhuma medição registrada.</p>'}`);document.querySelector('#measure-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=new FormData(e.target);await execute('measure',{id,quantities:c.items.map((_,i)=>Number(f.get('qty-'+i))),period:f.get('period')},'Medição registrada.');openContract(id);});};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(handleV03Action(b))return;if(b.dataset.action==='download-attachment'){attempt(()=>downloadAttachment(b.dataset.file,b.dataset.name));return;}const id=b.dataset.id,r=state.requests.find(r=>r.id===id);switch(b.dataset.action){case 'close':dialog.close();break;case 'new':requestForm();break;case 'edit':requestForm(r);break;case 'request':openRequest(id);break;case 'quotes':openQuotes(id);break;case 'add-quote':addQuote(id);break;case 'quote-files':openQuoteFiles(id,b.dataset.q);break;case 'select-quote':attempt(async()=>{await execute('suggest',{id,allocations:r.items.map(()=>b.dataset.q)});openQuotes(id);});break;case 'approve-engineering':attempt(async()=>{await execute('engineering',{id,services:r.items.map((_,index)=>document.querySelector('#service-'+index).value),justification:document.querySelector('#justification').value},'Necessidade aprovada. Suprimentos pode cotar.');openRequest(id);});break;case 'send-director':attempt(async()=>{await execute('send',{id,exception:document.querySelector('#exception').value},'Contratação enviada ao diretor.');openRequest(id);});break;case 'approve-director':attempt(async()=>{await execute('director',{id,decisions:r.items.map((_,index)=>document.querySelector(`[data-decision="${index}"]`).value),arrivals:r.items.map((_,index)=>document.querySelector(`[data-arrival="${index}"]`).value)},'Contratação aprovada.');openRequest(id);});break;case 'reject':modal('Devolver para correção',`<form id="reject-form"><label>Motivo da devolução<textarea name="reason" required></textarea></label><div class="actions"><button type="button" data-action="request" data-id="${id}">Cancelar</button><button class="primary">Devolver</button></div></form>`);document.querySelector('#reject-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{await execute('reject',{id,reason:new FormData(e.target).get('reason')},'Devolvido para correção.');openRequest(id);});};break;case 'order':openOrder(id);break;case 'withdraw':stockOut();break;case 'contract':openContract(id);break;}});
document.querySelector('#work').onchange=e=>{work=e.target.value;setServices();render();};
window.addEventListener('hashchange',()=>attempt(refresh));
document.querySelector('#refresh').onclick=()=>attempt(async()=>{await refresh();toast('Lista atualizada.');});
connect();

document.addEventListener('change',e=>{if(!e.target.matches('[data-decision]'))return;const select=e.target,index=Number(select.dataset.decision);const requestId=document.querySelector('.dialog-head h2')?.textContent.split(' · ')[0];const r=state.requests.find(r=>r.id===requestId),q=r?.quotes.find(q=>q.id===select.value);const input=document.querySelector(`[data-arrival="${index}"]`);if(q&&input&&!input.value){const d=new Date();d.setDate(d.getDate()+Number(q.days));input.value=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}});

function uploadField(id,title){return `<label style="margin-top:18px">${title}<input type="file" id="${id}" multiple><small>Até 10 MB por arquivo. Anexos compartilhados, com acesso autorizado.</small></label>`;}
function attachmentsView(files=[]){return files.length?`<div class="attachments">${files.map(f=>`<button type="button" class="small-button" data-action="download-attachment" data-file="${esc(f.id)}" data-name="${esc(f.name)}">↓ ${esc(f.name)} · ${Math.ceil(f.size/1024)} KB</button>`).join('')}</div>`:'<p class="subtitle">Sem anexos.</p>';}
async function storeAttachments(fileList,targetKind,targetId,purpose){const files=Array.from(fileList||[]);if(files.some(f=>f.size===0||f.size>10*1024*1024))throw Error('Cada anexo deve ter conteúdo e no máximo 10 MB.');const metadata=[];for(const f of files){const row=await api('/api/files',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({targetKind,targetId,purpose,name:f.name,size:f.size})});await api('/api/files/'+row.id,{method:'PUT',body:f});metadata.push(row);}return metadata;}
async function downloadAttachment(id,name){const r=await fetch('/api/files/'+encodeURIComponent(id),{credentials:'same-origin'});if(!r.ok)throw Error('Não foi possível baixar o anexo autorizado.');const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}

function openQuoteFiles(id,quoteId){const r=state.requests.find(r=>r.id===id),q=r.quotes.find(q=>q.id===quoteId);modal(`Anexos · ${esc(q.supplier)}`,`<form id="quote-files-form">${attachmentsView(q.attachments)}${uploadField('existing-quote-files','Adicionar anexos à proposta')}<div class="actions"><button type="button" data-action="quotes" data-id="${id}">Voltar</button><button class="primary">Salvar anexos</button></div></form>`);document.querySelector('#quote-files-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const files=document.querySelector('#existing-quote-files').files;if(!files.length)throw Error('Selecione um anexo.');const attachments=await storeAttachments(files,'request',id,'quote');await execute('quoteFiles',{id,quoteId,files:attachments.map(a=>a.id)},'Anexos da proposta registrados.');openQuotes(id);});};}

document.addEventListener('input',e=>{if(dialog.contains(e.target))document.querySelector('#error').textContent='';});

// Version 0.3: module navigation, shared registries and operational lists.
function currentPage(){return location.hash.slice(1)||'inicio';}
function filtersFor(page){return viewFilters[page]??={query:'',status:'',from:'',to:''};}
function todayISO(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
function renderNav(page,reveal=true){const activeGroup=nav.find(n=>n[0]===page)?.[3];if(reveal&&activeGroup)openGroups.add(activeGroup);const link=([id,icon,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="icon">${icon}</span>${label}</a>`;document.querySelector('#nav').innerHTML=link(nav[0])+['Compras','Contratos e Medições','Estoque','Cadastros','Relatórios'].map(group=>`<div class="nav-group"><button class="nav-group-button" data-action="nav-group" data-group="${group}" aria-label="${group}" aria-expanded="${openGroups.has(group)}"><span>${group}</span><span>${openGroups.has(group)?'⌄':'›'}</span></button><div class="nav-group-links" ${openGroups.has(group)?'':'hidden'}>${nav.filter(n=>n[3]===group).map(link).join('')}</div></div>`).join('');}
function documentMatches(o,f){const text=normalizeText([o.id,o.requestId,o.supplier,o.work,...o.items.flatMap(i=>[i.name,i.location])].join(' '));const status=o.items.every(i=>i.received>=i.qty)?'complete':o.items.some(i=>i.received>0)?'partial':'pending';return (!f.query||text.includes(normalizeText(f.query)))&&(!f.status||status===f.status)&&(!(f.from||f.to)||o.items.some(i=>i.estimatedArrival&&(!f.from||i.estimatedArrival>=f.from)&&(!f.to||i.estimatedArrival<=f.to)));}
function decoratePage(page){if(page==='inicio')return;const f=filtersFor(page);let states=[];if(['solicitacoes','cotacoes','aprovacoes'].includes(page))states=Object.entries(statusLabels);if(['pedidos','recebimentos'].includes(page))states=[['pending','Pendente'],['partial','Parcial'],['complete','Completo'],...(page==='recebimentos'?[['late','Atrasado']]:[])];if(page==='movimentos')states=[['in','Entrada'],['out','Saída']];const hasDate=['solicitacoes','cotacoes','aprovacoes','pedidos','recebimentos','movimentos','relatorios'].includes(page);const dateTitle=['solicitacoes','cotacoes','aprovacoes'].includes(page)?'Data necessária':page==='movimentos'?'Data do movimento':'Chegada estimada';const toolbar=document.createElement('div');toolbar.className='list-toolbar';toolbar.innerHTML=`<label class="search-field">Buscar nesta lista<input id="list-search" type="search" placeholder="Código, descrição, fornecedor ou local…" value="${esc(f.query)}"></label>${states.length?`<label>Etapa / situação<select data-filter="status"><option value="">Todas</option>${states.map(([id,label])=>`<option value="${id}" ${f.status===id?'selected':''}>${label}</option>`).join('')}</select></label>`:''}${hasDate?`<label>${dateTitle} · de<input type="date" data-filter="from" value="${esc(f.from)}"></label><label>Até<input type="date" data-filter="to" value="${esc(f.to)}"></label>`:''}<button data-action="clear-filters" class="small-button">Limpar filtros</button>`;content.querySelector('.page-heading').after(toolbar);if(f.from&&f.to&&f.from>f.to){const note=document.createElement('p');note.className='error';note.textContent='A data inicial deve ser anterior ou igual à data final.';toolbar.after(note);}const search=toolbar.querySelector('#list-search');search.oninput=e=>{const position=e.target.selectionStart;f.query=e.target.value;render();const next=content.querySelector('#list-search');next.focus();next.setSelectionRange(position,position);};toolbar.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{f[el.dataset.filter]=el.value;render();});if(['estoque','orcamento'].includes(page)&&f.query){content.querySelectorAll('tbody tr').forEach(row=>row.hidden=!normalizeText(row.innerText).includes(normalizeText(f.query)));}}
function visibleDeliveries(page=currentPage()){const f=filtersFor(page);return deliveryRows(filtered(state.orders),todayISO()).filter(row=>(!f.query||normalizeText([row.orderId,row.requestId,row.work,row.supplier,row.item.name,row.item.location].join(' ')).includes(normalizeText(f.query)))&&(!f.status||row.status===f.status)&&(!(f.from||f.to)||(row.item.estimatedArrival&&(!f.from||row.item.estimatedArrival>=f.from)&&(!f.to||row.item.estimatedArrival<=f.to))));}
function deliveryBadge(status){const labels={pending:'Pendente',partial:'Parcial',complete:'Completo',late:'Atrasado'};return `<span class="badge ${status==='late'?'returned':status==='complete'?'received':status==='partial'?'director':''}">${labels[status]}</span>`;}
function receivingPage(){const rows=visibleDeliveries();return heading('COMPRAS · ENTREGAS','Recebimentos','Previsão de chegada, localização e saldo de cada item.','<button data-action="export-deliveries">↓ Exportar CSV</button>')+panel('Acompanhamento por item',rows.length?table(['Pedido / obra','Material / local','Fornecedor','Necessário em','Chegada estimada','Recebido / pedido','Saldo','Situação',''],rows.map(r=>`<tr><td><strong>${esc(r.orderId)}</strong><small>${r.work}</small></td><td><strong>${esc(r.item.name)}</strong><small>${esc(r.item.location)}</small></td><td>${esc(r.supplier)}</td><td>${date(r.item.neededDate)}</td><td>${date(r.item.estimatedArrival)}</td><td>${r.item.received} / ${r.item.qty} ${esc(r.item.unit)}</td><td>${r.pending}</td><td>${deliveryBadge(r.status)}</td><td><button data-action="order" data-id="${r.orderId}">Conferir entrega →</button></td></tr>`).join('')):empty('Nenhuma entrega encontrada','Emita um pedido ou ajuste os filtros para acompanhar seus itens.'),`${rows.length} ITENS`);}
function visibleMovements(){const f=filtersFor('movimentos');return filtered(state.movements).filter(m=>(!f.status||m.kind===f.status)&&(!f.query||normalizeText([m.work,m.who,m.nf,m.orderId,m.floor,materials.find(i=>i.id===m.material)?.name].join(' ')).includes(normalizeText(f.query)))&&(!f.from||m.at.slice(0,10)>=f.from)&&(!f.to||m.at.slice(0,10)<=f.to)).slice().reverse();}
function movementsPage(){const rows=visibleMovements();return heading('ESTOQUE · RASTREABILIDADE','Movimentações','Entradas e saídas com documento, responsável e destino.','<div class="actions" style="margin:0"><button data-action="export-movements">↓ Exportar CSV</button><button class="primary" data-action="withdraw">Registrar saída</button></div>')+panel('Histórico de movimentos',rows.length?table(['Data','Material','Obra','Movimento','Quantidade','Serviço / local','Responsável / documento'],rows.map(m=>`<tr><td>${date(m.at)}</td><td>${esc(materials.find(i=>i.id===m.material)?.name)}</td><td>${m.work}</td><td><span class="badge ${m.kind==='in'?'received':'quoting'}">${m.kind==='in'?'Entrada':'Saída'}</span></td><td>${m.qty}</td><td>${esc(services.find(s=>s.id===m.service)?.name||'—')}<small>${esc(m.floor||'')}</small></td><td>${esc(m.who)}<small>${esc(m.nf||m.orderId||'')}</small></td></tr>`).join('')):empty('Nenhuma movimentação encontrada','Ajuste os filtros ou registre uma movimentação.'),`${rows.length} REGISTROS`);}
function measurementsPage(contracts){const rows=contracts.flatMap(c=>c.measurements.map(m=>({...m,contract:c}))).slice().reverse();return heading('CONTRATOS E MEDIÇÕES','Medições de serviços','Conferência do executado e histórico vinculado a cada contrato.')+panel('Contratos disponíveis para medição',contracts.length?table(['Contrato / obra','Fornecedor','Valor contratado (itens)','Medido acumulado',''],contracts.map(c=>`<tr><td><strong>${c.id}</strong><small>${c.work}</small></td><td>${esc(c.supplier)}</td><td>${money(c.items.reduce((s,i)=>s+i.qty*i.price,0))}</td><td>${money(c.measurements.reduce((s,m)=>s+m.value,0))}</td><td><button data-action="contract" data-id="${c.id}">Registrar medição →</button></td></tr>`).join('')):empty('Nenhum contrato encontrado','Contrate um serviço para registrar sua execução.'))+panel('Medições registradas',rows.length?table(['Contrato','Fornecedor','Período','Valor medido','Data'],rows.map(m=>`<tr><td>${m.contract.id}</td><td>${esc(m.contract.supplier)}</td><td>${esc(m.period)}</td><td>${money(m.value)}</td><td>${date(m.at)}</td></tr>`).join('')):empty('Nenhuma medição registrada','As medições aparecerão após a conferência dos serviços.'));}
function materialPage(){const f=filtersFor('cadastros'),rows=materials.filter(m=>normalizeText([m.id,m.name,m.unit].join(' ')).includes(normalizeText(f.query)));return heading('CADASTROS · EMPRESA','Materiais e insumos','Catálogo compartilhado, com saldo independente por obra.','<button class="primary" data-action="new-material">＋ Novo material</button>')+panel('Catálogo de materiais',rows.length?table(['Código','Material','Unidade',...state.works.map(w=>w.name+' · saldo')],rows.map(m=>`<tr><td>${esc(m.id)}</td><td><strong>${esc(m.name)}</strong></td><td>${esc(m.unit)}</td>${state.works.map(w=>`<td>${balance(state,w.id,m.id)}</td>`).join('')}</tr>`).join('')):empty('Nenhum material cadastrado','Suprimentos pode cadastrar os materiais autorizados.'));}
function supplierPage(){const f=filtersFor('fornecedores'),rows=state.suppliers.filter(s=>normalizeText([s.name,s.document,s.contact,s.email].join(' ')).includes(normalizeText(f.query)));return heading('CADASTROS · EMPRESA','Fornecedores','Contatos e identificação compartilhados entre as obras.','<button class="primary" data-action="new-supplier">＋ Novo fornecedor</button>')+panel('Cadastro de fornecedores',rows.length?table(['Fornecedor','CNPJ / identificação','Contato','E-mail / telefone',''],rows.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.document||'Não informado')}</td><td>${esc(s.contact||'—')}</td><td>${esc(s.email||'—')}<small>${esc(s.phone||'')}</small></td><td><button data-action="edit-supplier" data-id="${s.id}">Editar contato</button></td></tr>`).join('')):empty('Nenhum fornecedor encontrado','Os fornecedores das propostas são incluídos aqui automaticamente.'),`${rows.length} FORNECEDORES`);}
function materialForm(){modal('Novo material',`<form id="material-form"><div class="fields"><label class="wide">Descrição do material<input name="name" required placeholder="Ex.: Areia média"></label><label>Unidade<input name="unit" required placeholder="Ex.: m³"></label></div><div class="note">O material será disponibilizado para solicitações nas duas obras. Saldo inicial zero; unidades e nomes dos materiais existentes são preservados.</div><div class="actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Cadastrar material</button></div></form>`);document.querySelector('#material-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const f=new FormData(e.target),name=f.get('name').trim(),unit=f.get('unit').trim();if(!name||!unit)throw Error('Informe descrição e unidade.');if(materials.some(m=>normalizeText(m.name)===normalizeText(name)))throw Error('Este material já está cadastrado.');await execute('material',{name,unit,work:catalogWork()},'Material disponível no catálogo e nas solicitações.');dialog.close();});};}
function supplierForm(id){const existing=state.suppliers.find(s=>s.id===id);modal(existing?'Editar contato do fornecedor':'Novo fornecedor',`<form id="supplier-form"><div class="fields"><label class="wide">Nome / razão social<input name="name" required ${existing?'readonly':''} value="${esc(existing?.name||'')}"></label><label>CNPJ / identificação (opcional)<input name="document" value="${esc(existing?.document||'')}"></label><label>Contato<input name="contact" value="${esc(existing?.contact||'')}"></label><label>E-mail<input name="email" type="email" value="${esc(existing?.email||'')}"></label><label>Telefone<input name="phone" value="${esc(existing?.phone||'')}"></label></div><div class="note">Cadastro compartilhado para todas as obras. Na cotação, você pode usar um fornecedor cadastrado ou informar um novo.</div><div class="actions"><button type="button" data-action="close">Cancelar</button><button class="primary">Salvar fornecedor</button></div></form>`);document.querySelector('#supplier-form').onsubmit=e=>{e.preventDefault();attempt(async()=>{const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(key=>data[key]=data[key].trim());if(!data.name)throw Error('Informe o nome do fornecedor.');if(state.suppliers.some(s=>s.id!==id&&(normalizeText(s.name)===normalizeText(data.name)||(data.document&&s.document.replace(/\D/g,'')&&s.document.replace(/\D/g,'')===data.document.replace(/\D/g,'')))))throw Error('Fornecedor já cadastrado com esse nome ou identificação.');await execute('supplier',{...data,...(existing?{id}:{}),work:catalogWork()},'Cadastro do fornecedor salvo.');dialog.close();});};}
function reportsPage(){const f=filtersFor('relatorios'),requests=filterRequests(filtered(state.requests),{query:f.query});const rows=visibleDeliveries('relatorios');const pending=rows.filter(r=>r.status!=='complete');const late=pending.filter(r=>r.status==='late');return heading('RELATÓRIOS · SUPRIMENTOS','Acompanhamento operacional','Necessidades, entregas e pendências das obras selecionadas.','<button data-action="export-deliveries">↓ Exportar entregas em CSV</button>')+`<div class="cards"><div class="card"><div class="card-label">Solicitações na obra / busca</div><div class="metric">${requests.length}</div><small>Contagem por solicitação</small></div><div class="card"><div class="card-label">Itens com entrega pendente</div><div class="metric">${pending.length}</div><small>Dentro dos filtros de chegada</small></div><div class="card"><div class="card-label">Itens com previsão vencida</div><div class="metric">${late.length}</div><small>Previsão anterior a hoje, com saldo</small></div><div class="card accent"><div class="card-label">Itens recebidos integralmente</div><div class="metric">${rows.filter(r=>r.status==='complete').length}</div><small>Sem saldo de entrega</small></div></div><div class="note">O período desta tela filtra a chegada estimada das entregas. A contagem de solicitações considera a obra e a busca. Os registros operacionais não representam pagamentos.</div>`+panel('Solicitações por etapa',table(['Etapa','Quantidade'],Object.entries(statusLabels).map(([id,label])=>`<tr><td>${label}</td><td>${requests.filter(r=>r.status===id).length}</td></tr>`).join('')))+panel('Entregas com previsão vencida',late.length?table(['Pedido','Obra','Material / local','Fornecedor','Previsão','Saldo',''],late.map(r=>`<tr><td>${r.orderId}</td><td>${r.work}</td><td>${esc(r.item.name)}<small>${esc(r.item.location)}</small></td><td>${esc(r.supplier)}</td><td>${date(r.item.estimatedArrival)}</td><td>${r.pending} ${esc(r.item.unit)}</td><td><button data-action="order" data-id="${r.orderId}">Abrir pedido →</button></td></tr>`).join('')):empty('Sem entregas atrasadas nos filtros','O relatório considera a previsão registrada em cada item.'));}
function downloadCSV(name,rows){const url=URL.createObjectURL(new Blob([csvContent(rows)],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function handleV03Action(b){switch(b.dataset.action){case 'audit':attempt(async()=>{const rows=await api('/api/audit');modal('Histórico de ações',table(['Data e hora','Obra','Registro','Autor','Ação / motivo'],rows.map(h=>`<tr><td>${esc(new Date(h.at).toLocaleString('pt-BR'))}</td><td>${esc(h.work_id)}</td><td>${esc(h.record_id)}</td><td>${esc(h.actor_name)}<small>${esc(h.actor_id)}</small></td><td>${esc(actionLabels[h.action]||h.action)}<small>${esc(h.reason)}</small></td></tr>`).join('')));});return true;case 'reconnect':attempt(connect);return true;case 'nav-group':if(openGroups.has(b.dataset.group))openGroups.delete(b.dataset.group);else openGroups.add(b.dataset.group);renderNav(currentPage(),false);return true;case 'clear-filters':viewFilters[currentPage()]={query:'',status:'',from:'',to:''};render();return true;case 'new-material':materialForm();return true;case 'new-supplier':supplierForm();return true;case 'edit-supplier':supplierForm(b.dataset.id);return true;case 'export-deliveries':downloadCSV('FeS-entregas.csv',[['Pedido','Obra','Fornecedor','Material','Local','Data necessária','Chegada estimada','Quantidade pedida','Recebido','Saldo','Unidade','Situação'],...visibleDeliveries().map(r=>[r.orderId,r.work,r.supplier,r.item.name,r.item.location,r.item.neededDate,r.item.estimatedArrival,r.item.qty,r.item.received,r.pending,r.item.unit,r.status])]);return true;case 'export-movements':downloadCSV('FeS-movimentacoes.csv',[['Data','Obra','Material','Tipo','Quantidade','Responsável','Documento','Serviço'],...visibleMovements().map(m=>[m.at,m.work,materials.find(i=>i.id===m.material)?.name,m.kind,m.qty,m.who,m.nf||m.orderId||'',m.service])]);return true;default:return false;}}

function restrictControls(){const roles={'new':'almoxarifado','edit':'almoxarifado','approve-engineering':'engenharia','add-quote':'suprimentos','select-quote':'suprimentos','quote-files':'suprimentos','send-director':'suprimentos','approve-director':'diretor','withdraw':'almoxarifado','new-material':'suprimentos','new-supplier':'suprimentos','edit-supplier':'suprimentos'};document.querySelectorAll('[data-action]').forEach(b=>{const role=roles[b.dataset.action];const r=state.requests.find(r=>r.id===b.dataset.id);if(role)b.hidden=!permitted(role,r?.work);if(b.dataset.action==='reject')b.hidden=!permitted(r?.status==='director'?'diretor':'engenharia',r?.work);});const id=document.querySelector('.dialog-head h2')?.textContent.split(' · ')[0],o=state.orders.find(o=>o.id===id),c=state.contracts.find(c=>c.id===id);if(o){for(const [form,role] of [['arrival-form','suprimentos'],['order-files-form','suprimentos'],['receive-form','almoxarifado']]){document.querySelector('#'+form)?.querySelectorAll('input,button').forEach(el=>el.disabled=!permitted(role,o.work));}}if(c)document.querySelector('#measure-form')?.querySelectorAll('input,button').forEach(el=>el.disabled=!permitted('engenharia',c.work));}

const actionLabels={create:'Solicitação criada',edit:'Solicitação revisada',engineering:'Necessidade aprovada',quote:'Proposta cadastrada',suggest:'Fornecedores sugeridos',send:'Enviado ao diretor',reject:'Devolução',director:'Contratação aprovada',arrival:'Previsão atualizada',receive:'Recebimento',withdraw:'Saída de estoque',measure:'Medição',material:'Material cadastrado',supplier:'Fornecedor atualizado',quoteFiles:'Anexos da proposta',orderFiles:'Anexos do pedido'};
